package {
    default_applicable_licenses: ["droidloom_license"],
}

license {
    name: "droidloom_license",
    visibility: [":__subpackages__"],
    license_kinds: ["SPDX-license-identifier-GPL-3.0-or-later"],
    license_text: ["LICENSE", "LICENSES/GPL-3.0-or-later.txt"],
}

android_app {
    name: "DroidloomIME",
    manifest: "android/framework/droidloom-ime/AndroidManifest.xml",
    srcs: ["android/framework/droidloom-ime/src/**/*.java"],
    resource_dirs: ["android/framework/droidloom-ime/res"],
    sdk_version: "37",
    min_sdk_version: "31",
    certificate: "testkey",
    // This tiny SDK-only app needs no Bazel resource processor.
    use_resource_processor: false,
    optimize: { enabled: false },
    lint: { enabled: false },
}

android_app {
    name: "DroidloomHome",
    manifest: "android/framework/droidloom-home/AndroidManifest.xml",
    srcs: ["android/framework/droidloom-home/src/**/*.java"],
    resource_dirs: ["android/framework/droidloom-home/res"],
    sdk_version: "37",
    min_sdk_version: "31",
    certificate: "testkey",
    use_resource_processor: false,
    optimize: { enabled: false },
    lint: { enabled: false },
}

android_app {
    name: "DroidloomSystemUI",
    manifest: "android/framework/droidloom-systemui/AndroidManifest.xml",
    srcs: ["android/framework/droidloom-systemui/src/**/*.java",
        "android/framework/cpu-placement/src/com/android/droidloom/runtime/CpuPlacement.java"],
    resource_dirs: [],
    platform_apis: true,
    system_ext_specific: true,
    privileged: true,
    certificate: "platform",
    use_resource_processor: false,
    optimize: { enabled: false },
    lint: { enabled: false },
}

// Runs without an Activity or UI event, under app_process as Android shell.
java_library {
    name: "DroidloomSystemUIProbe",
    srcs: [
        "android/framework/droidloom-systemui/src/com/android/systemui/StatusBarCallbacks.java",
        "android/framework/droidloom-systemui/src/com/android/systemui/Unsupported.java",
        "android/framework/droidloom-systemui/src/com/android/systemui/compat/*.java",
        "android/framework/droidloom-systemui/tests/CallbacksProbe.java",
    ],
    installable: true,
    dex_preopt: { enabled: false },
    optimize: { enabled: false },
    lint: { enabled: false },
}

// Safe, Binder-independent state used by the Android Composer service. These
// modules are vendor-only: Droidloom reuses the pinned AOSP system partitions
// and builds its own vendor partition.
rust_library {
    name: "libdroidloom_transport",
    crate_name: "droidloom_transport",
    crate_root: "graphics/droidloom-transport/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "libserde",
        "libthiserror",
    ],
}

// Composer V5 service entry point. Android init owns the privileged lifecycle
// socket while the Droidloom runtime supplies the private Denial endpoint and
// render node inside the cell's restricted /dev.
rust_binary {
    name: "android.hardware.graphics.composer3-service.droidloom",
    crate_name: "droidloom_composer_service",
    crate_root: "graphics/droidloom-composer-service/src/main.rs",
    edition: "2021",
    vendor: true,
    relative_install_path: "hw",
    init_rc: ["android/device/droidloom_arm64/droidloom-composer.rc"],
    vintf_fragments: ["android/device/droidloom_arm64/droidloom-composer.xml"],
    rustlibs: [
        "android.hardware.graphics.composer3-V5-rust",
        "libbinder_rs",
        "libdroidloom_composer",
        "libdroidloom_composer_aidl",
        "libdroidloom_denial_ipc",
        "libdroidloom_denial_protocol",
        "libdroidloom_input_protocol",
        "libdroidloom_minigbm",
        "libdroidloom_syncobj",
        "libdroidloom_surface_bridge",
        "libdroidloom_task_control",
        "libdroidloom_transport",
    ],
}

// Safe fixed-record encoder used after Denial has selected one Android task.
rust_library {
    name: "libdroidloom_input_protocol",
    crate_name: "droidloom_input_protocol",
    crate_root: "graphics/droidloom-input-protocol/src/lib.rs",
    edition: "2021",
    vendor: true,
    // The record codec is tiny and has a single Android consumer. Linking it
    // directly avoids adding a new vendor partition ABI/runtime file.
    prefer_rlib: true,
    no_stdlibs: true,
}

// The routing, gesture identity, and policy remain in Rust. This framework
// bridge contains the long-running input adapter plus a one-shot application
// metadata adapter; Android remains authoritative for MotionEvents, launcher
// intent resolution, localized labels, and adaptive icons.
java_binary {
    name: "droidloom-input-bridge",
    vendor: true,
    srcs: ["android/framework/droidloom-input-bridge/src/**/*.java",
        "android/framework/cpu-placement/src/com/android/droidloom/runtime/CpuPlacement.java"],
    wrapper: "android/framework/droidloom-input-bridge/droidloom-input-bridge",
    init_rc: ["android/framework/droidloom-input-bridge/droidloom-input-bridge.rc"],
    // TaskStackListener is a pinned platform API. The root bridge observes
    // Android launches without intercepting or reconstructing their intents.
    sdk_version: "core_platform",
    libs: ["framework"],
    // This privileged platform adapter is built from plain Java and is covered
    // by the focused runtime tests. Avoid pulling Android's global app-lint
    // plugin graph into the intentionally sparse Droidloom source checkout.
    lint: {
        enabled: false,
    },
}

// Low-frequency privileged lifecycle protocol. This reserves/configures a
// dedicated display before app launch, then binds the real Android task ID.
rust_library {
    name: "libdroidloom_task_control",
    crate_name: "droidloom_task_control",
    crate_root: "graphics/droidloom-task-control/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "libthiserror",
    ],
}

// Privileged one-shot primitive invoked by the host supervisor inside the
// Android cell. It uses Android's own activity command service, discovers the
// resulting leaf task on the newly reserved display, and commits the real task
// ID through the two-phase control protocol.
rust_library {
    name: "libdroidloom_task_launcher",
    crate_name: "droidloom_task_launcher",
    crate_root: "android/framework/droidloom-task-launcher/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "libdroidloom_denial_ipc",
        "libdroidloom_task_control",
    ],
}

rust_binary {
    name: "droidloom-task-launcher",
    crate_name: "droidloom_task_launcher_bin",
    crate_root: "android/framework/droidloom-task-launcher/src/main.rs",
    edition: "2021",
    vendor: true,
    rustlibs: ["libdroidloom_task_launcher"],
}

// Development-only LMKD protocol endpoint. The Android cell's memory budget
// is enforced outside Android; this keeps ActivityManager non-blocking without
// claiming or implementing process-killing policy inside the guest.
rust_binary {
    name: "droidloom-lmkd-compat",
    crate_name: "droidloom_lmkd_compat",
    crate_root: "android/lmkd-compat/droidloom-lmkd-compat.rs",
    edition: "2021",
    vendor: true,
    rustlibs: ["liblibc"],
}

// Development-only compatibility boundary for host kernels that cannot mount
// an otherwise valid APEX payload filesystem. The supervisor projects an
// already-verified classpath subset below /droidloom; this one-shot bind
// mounts it below /apex before delegating to Android's derive_classpath.
rust_binary {
    name: "droidloom-classpath-wrapper",
    crate_name: "droidloom_classpath_wrapper",
    crate_root: "android/runtime/droidloom-classpath-wrapper/src/main.rs",
    edition: "2021",
    vendor: true,
}

// Versioned Denial-native SOCK_SEQPACKET codec. The socket/SCM_RIGHTS adapter
// stays platform-specific; this safe module validates every byte, bound, and
// descriptor role before either side mutates compositor state.
rust_library {
    name: "libdroidloom_denial_protocol",
    crate_name: "droidloom_denial_protocol",
    crate_root: "graphics/droidloom-denial-protocol/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "libdroidloom_transport",
        "libthiserror",
    ],
}

// Narrow audited Unix socket/SCM_RIGHTS adapter. Unsafe code is confined to
// sendmsg/recvmsg and ancillary parsing; its public boundary owns every
// received FD and pairs it with a role from the safe protocol codec.
rust_library {
    name: "libdroidloom_denial_ipc",
    crate_name: "droidloom_denial_ipc",
    crate_root: "graphics/droidloom-denial-ipc/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "libdroidloom_denial_protocol",
        "liblibc",
        "libthiserror",
    ],
}

// Shared DRM syncobj timeline operations for the Android Composer and Denial
// endpoint. This wraps opaque task timelines and sync_file point transfers;
// Android never receives a KMS/card node.
rust_library {
    name: "libdroidloom_cpu_placement",
    crate_name: "droidloom_cpu_placement",
    crate_root: "runtime/droidloom-cpu-placement/src/lib.rs",
    edition: "2024",
    vendor_available: true,
    rustlibs: ["liblibc"],
}

rust_library {
    name: "libdroidloom_syncobj",
    crate_name: "droidloom_syncobj",
    crate_root: "graphics/droidloom-syncobj/src/lib.rs",
    edition: "2021",
    vendor: true,
    rlibs: ["libdroidloom_cpu_placement"],
    rustlibs: [
        "libdrm_rust",
        "liblibc",
        "libthiserror",
    ],
}

// Fixed-record, cell-private handoff used when SurfaceFlinger renders the
// complete built-in display directly into a Denial-owned target.
rust_library {
    name: "libdroidloom_surface_bridge",
    crate_name: "droidloom_surface_bridge",
    crate_root: "graphics/droidloom-surface-bridge/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: ["libthiserror"],
}

rust_library {
    name: "libdroidloom_composer",
    crate_name: "droidloom_composer",
    crate_root: "graphics/droidloom-composer/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "libdroidloom_denial_protocol",
        "libdroidloom_transport",
        "libthiserror",
    ],
}

// Exact parser for the pinned minigbm cros_gralloc_handle payload. Descriptor
// ownership remains in the Binder-facing adapter.
rust_library {
    name: "libdroidloom_minigbm",
    crate_name: "droidloom_minigbm",
    crate_root: "graphics/droidloom-minigbm/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "libdroidloom_transport",
        "libthiserror",
    ],
}

// Soong-only boundary between frozen Composer V5 Binder types and the safe
// platform-independent state machine. Keeping this as a vendor module forces
// Soong to select the vendor AIDL variant used by the eventual HAL service.
rust_library {
    name: "libdroidloom_composer_aidl",
    crate_name: "droidloom_composer_aidl",
    crate_root: "graphics/droidloom-composer-aidl/src/lib.rs",
    edition: "2021",
    vendor: true,
    rustlibs: [
        "android.hardware.common-V2-rust",
        "android.hardware.drm.common-V1-rust",
        "android.hardware.graphics.common-V7-rust",
        "android.hardware.graphics.composer3-V5-rust",
        "libbinder_rs",
        "libdroidloom_composer",
        "libdroidloom_denial_ipc",
        "libdroidloom_denial_protocol",
        "libdroidloom_minigbm",
        "libdroidloom_syncobj",
        "libdroidloom_transport",
        "libthiserror",
    ],
    shared_libs: [
        "libEGL",
        "libGLESv2",
    ],
}

// Exercises the Soong-only Composer boundary against the exact frozen Android
// AIDL types. These tests cover platform semantics that cannot be represented
// by the host Cargo workspace, including SOLID_COLOR layer commands.
rust_test {
    name: "droidloom-composer-aidl-tests",
    crate_name: "droidloom_composer_aidl_tests",
    crate_root: "graphics/droidloom-composer-aidl/src/lib.rs",
    edition: "2021",
    vendor: true,
    test_suites: ["general-tests"],
    rustlibs: [
        "android.hardware.common-V2-rust",
        "android.hardware.drm.common-V1-rust",
        "android.hardware.graphics.common-V7-rust",
        "android.hardware.graphics.composer3-V5-rust",
        "libbinder_rs",
        "libdroidloom_composer",
        "libdroidloom_denial_ipc",
        "libdroidloom_denial_protocol",
        "libdroidloom_minigbm",
        "libdroidloom_syncobj",
        "libdroidloom_transport",
        "libthiserror",
    ],
    shared_libs: [
        "libEGL",
        "libGLESv2",
    ],
}

// Installed only by explicit clipboard validation, never by runtime packaging.
android_app {
    name: "DroidloomClipboardProbe",
    manifest: "android/framework/droidloom-systemui/tests/clipboard-probe/AndroidManifest.xml",
    srcs: ["android/framework/droidloom-systemui/tests/clipboard-probe/*.java"],
    resource_dirs: [],
    platform_apis: true,
    certificate: "platform",
    use_resource_processor: false,
    optimize: { enabled: false },
    lint: { enabled: false },
}

// Test-only notification producer, installed explicitly for integration validation.
android_app {
    name: "DroidloomNotificationProbe",
    manifest: "android/framework/droidloom-systemui/tests/notification-probe/AndroidManifest.xml",
    srcs: ["android/framework/droidloom-systemui/tests/notification-probe/*.java"],
    resource_dirs: [],
    platform_apis: true,
    certificate: "platform",
    use_resource_processor: false,
    optimize: { enabled: false },
    lint: { enabled: false },
}

//! Compile the narrow EGL/GLES ABI shim used by the Rust probe.

fn main() {
    cc::Build::new()
        .file("src/egl_renderer.c")
        .flag_if_supported("-std=c11")
        .warnings(true)
        .compile("droidloom_egl_renderer");
    println!("cargo:rustc-link-lib=EGL");
    println!("cargo:rustc-link-lib=GLESv2");
    println!("cargo:rerun-if-changed=src/egl_renderer.c");
}

//! End-to-end GLES → DMA-BUF → Denial DRM-syncobj presentation probe.

use std::ffi::{CStr, c_char, c_int, c_void};
use std::fs::{File, OpenOptions};
use std::os::fd::{AsFd, AsRawFd, FromRawFd, OwnedFd};
use std::path::PathBuf;
use std::ptr::NonNull;
use std::sync::mpsc;
use std::time::Duration;

use clap::Parser;
use drm::control::{Device as ControlDevice, syncobj};
use drm_fourcc::{DrmFourcc, DrmModifier};
use droidloom_transport::{
    BufferId, BufferMetadata, Configure, Damage, FormatModifier, FrameId, PlaneMetadata,
    PresentationState,
};
use gbm::{BufferObject, Device as GbmDevice, Modifier};
use serde::Serialize;
use smithay_client_toolkit::compositor::{CompositorHandler, CompositorState};
use smithay_client_toolkit::dmabuf::{DmabufFeedback, DmabufHandler, DmabufState};
use smithay_client_toolkit::output::{OutputHandler, OutputState};
use smithay_client_toolkit::registry::{ProvidesRegistryState, RegistryState};
use smithay_client_toolkit::registry_handlers;
use smithay_client_toolkit::shell::WaylandSurface;
use smithay_client_toolkit::shell::xdg::XdgShell;
use smithay_client_toolkit::shell::xdg::window::{
    Window, WindowConfigure, WindowDecorations, WindowHandler,
};
use thiserror::Error;
use wayland_client::globals::{BindError, registry_queue_init};
use wayland_client::protocol::{wl_buffer, wl_output, wl_surface};
use wayland_client::{Connection, QueueHandle};
use wayland_protocols::wp::linux_dmabuf::zv1::client::{
    zwp_linux_buffer_params_v1, zwp_linux_dmabuf_feedback_v1,
};
use wayland_protocols::wp::linux_drm_syncobj::v1::client::{
    wp_linux_drm_syncobj_manager_v1::WpLinuxDrmSyncobjManagerV1,
    wp_linux_drm_syncobj_surface_v1::WpLinuxDrmSyncobjSurfaceV1,
    wp_linux_drm_syncobj_timeline_v1::WpLinuxDrmSyncobjTimelineV1,
};

const ACQUIRE_POINT: u64 = 1;
const RELEASE_POINT: u64 = 2;
const VISIBLE_FRAME_CALLBACKS: u32 = 120;

#[derive(Debug, Parser)]
#[command(name = "droidloom-dmabuf-probe", version, about)]
struct Cli {
    /// DRM render node; card/KMS nodes are rejected.
    #[arg(long, default_value = "/dev/dri/renderD128")]
    render_node: PathBuf,
    /// Number of presentation-paced callbacks before cleanly detaching.
    #[arg(long, default_value_t = VISIBLE_FRAME_CALLBACKS)]
    frame_callbacks: u32,
}

#[derive(Debug)]
struct DrmNode(File);

impl AsFd for DrmNode {
    fn as_fd(&self) -> std::os::fd::BorrowedFd<'_> {
        self.0.as_fd()
    }
}

impl drm::Device for DrmNode {}
impl ControlDevice for DrmNode {}

impl DrmNode {
    fn try_clone(&self) -> std::io::Result<Self> {
        self.0.try_clone().map(Self)
    }
}

#[repr(C)]
struct NativeEglRenderer {
    _opaque: [u8; 0],
}

unsafe extern "C" {
    fn droidloom_egl_renderer_create(
        gbm_device: *mut c_void,
        error: *mut c_char,
        error_size: usize,
    ) -> *mut NativeEglRenderer;
    fn droidloom_egl_renderer_name(renderer: *const NativeEglRenderer) -> *const c_char;
    fn droidloom_egl_render_dmabuf(
        renderer: *mut NativeEglRenderer,
        width: c_int,
        height: c_int,
        fourcc: u32,
        modifier: u64,
        dma_buf_fd: c_int,
        offset: u32,
        stride: u32,
        fence_fd: *mut c_int,
        error: *mut c_char,
        error_size: usize,
    ) -> c_int;
    fn droidloom_egl_renderer_destroy(renderer: *mut NativeEglRenderer);
    fn droidloom_import_sync_file(
        drm_fd: c_int,
        syncobj_handle: u32,
        sync_file_fd: c_int,
        error: *mut c_char,
        error_size: usize,
    ) -> c_int;
}

#[derive(Debug)]
struct EglRenderer(NonNull<NativeEglRenderer>);

#[derive(Clone, Copy)]
struct EglTarget<'a> {
    width: u32,
    height: u32,
    fourcc: u32,
    modifier: u64,
    dma_buf: &'a OwnedFd,
    offset: u32,
    stride: u32,
}

impl EglRenderer {
    fn new(gbm_device: *mut c_void) -> Result<Self, ProbeError> {
        let mut error = [0_i8; 512];
        // SAFETY: the GBM device outlives this EGL wrapper and the error array is writable.
        let renderer =
            unsafe { droidloom_egl_renderer_create(gbm_device, error.as_mut_ptr(), error.len()) };
        NonNull::new(renderer)
            .map(Self)
            .ok_or_else(|| ProbeError::Egl(c_error(&error)))
    }

    fn renderer_name(&self) -> String {
        // SAFETY: the C renderer owns a NUL-terminated fixed-size name for its lifetime.
        let name = unsafe { droidloom_egl_renderer_name(self.0.as_ptr()) };
        if name.is_null() {
            "unknown".to_owned()
        } else {
            // SAFETY: a non-null name is NUL-terminated by the C renderer.
            unsafe { CStr::from_ptr(name) }
                .to_string_lossy()
                .into_owned()
        }
    }

    fn render(&mut self, target: EglTarget<'_>) -> Result<OwnedFd, ProbeError> {
        let width = i32::try_from(target.width).map_err(|_| ProbeError::Dimension)?;
        let height = i32::try_from(target.height).map_err(|_| ProbeError::Dimension)?;
        let mut fence = -1;
        let mut error = [0_i8; 512];
        // SAFETY: all pointers are valid for the call; C borrows the DMA-BUF and returns
        // ownership of a newly duplicated native-fence FD on success.
        let result = unsafe {
            droidloom_egl_render_dmabuf(
                self.0.as_ptr(),
                width,
                height,
                target.fourcc,
                target.modifier,
                target.dma_buf.as_raw_fd(),
                target.offset,
                target.stride,
                &raw mut fence,
                error.as_mut_ptr(),
                error.len(),
            )
        };
        if result != 0 || fence < 0 {
            Err(ProbeError::Egl(c_error(&error)))
        } else {
            // SAFETY: successful C return transfers one valid, newly duplicated FD.
            Ok(unsafe { OwnedFd::from_raw_fd(fence) })
        }
    }
}

impl Drop for EglRenderer {
    fn drop(&mut self) {
        // SAFETY: the pointer is unique and was returned by the matching constructor.
        unsafe { droidloom_egl_renderer_destroy(self.0.as_ptr()) };
    }
}

fn c_error(buffer: &[c_char]) -> String {
    // SAFETY: all C error writers use snprintf into this initialized fixed-size array.
    unsafe { CStr::from_ptr(buffer.as_ptr()) }
        .to_string_lossy()
        .into_owned()
}

#[derive(Debug, Error)]
enum ProbeError {
    #[error("render node must be /dev/dri/renderD<number>, not {0}")]
    RenderNodePolicy(PathBuf),
    #[error("I/O failure: {0}")]
    Io(#[from] std::io::Error),
    #[error("Wayland connection failure: {0}")]
    Connect(#[from] wayland_client::ConnectError),
    #[error("Wayland global enumeration failure: {0}")]
    Global(#[from] wayland_client::globals::GlobalError),
    #[error("Wayland toolkit global failure: {0}")]
    ToolkitGlobal(#[from] smithay_client_toolkit::error::GlobalError),
    #[error("Wayland bind failure: {0}")]
    Bind(#[from] BindError),
    #[error("Wayland dispatch failure: {0}")]
    Dispatch(#[from] wayland_client::DispatchError),
    #[error("EGL/GLES failure: {0}")]
    Egl(String),
    #[error("Denial does not advertise linux-dmabuf v4 feedback")]
    DmabufV4Required,
    #[error("Denial feedback lacks linear XRGB8888 import")]
    MissingLinearXrgb,
    #[error("GBM allocated {0} planes; the minimum probe requires exactly one")]
    PlaneCount(u32),
    #[error("configured dimensions exceed signed Wayland/EGL bounds")]
    Dimension,
    #[error("DRM syncobj operation failed: {0}")]
    Syncobj(String),
    #[error("release point was not signalled within five seconds")]
    ReleaseTimeout,
    #[error("transport invariant failed: {0}")]
    Transport(#[from] droidloom_transport::TransportError),
    #[error("probe callback failed: {0}")]
    Callback(String),
}

#[derive(Debug, Serialize)]
struct ProbeEvidence {
    schema_version: u32,
    render_node: PathBuf,
    gbm_backend: String,
    gl_renderer: String,
    width: u32,
    height: u32,
    fourcc: u32,
    modifier: u64,
    plane_count: u32,
    stride: u32,
    producer: &'static str,
    acquire_fence: &'static str,
    compositor_sync: &'static str,
    release_observed: bool,
    cpu_readback: bool,
    steady_state_cpu_copies: u32,
    drm_card_opened: bool,
    frame_callbacks: u32,
}

struct App {
    registry_state: RegistryState,
    output_state: OutputState,
    dmabuf_state: DmabufState,
    feedback: Option<DmabufFeedback>,
    window: Option<Window>,
    sync_surface: Option<WpLinuxDrmSyncobjSurfaceV1>,
    timeline: Option<WpLinuxDrmSyncobjTimelineV1>,
    timeline_handle: Option<syncobj::Handle>,
    drm: DrmNode,
    gbm: GbmDevice<File>,
    egl: EglRenderer,
    bo: Option<BufferObject<()>>,
    buffer: Option<wl_buffer::WlBuffer>,
    transport: PresentationState,
    submitted_frame: Option<FrameId>,
    render_node: PathBuf,
    target_callbacks: u32,
    callbacks: u32,
    detached: bool,
    exit: bool,
    fatal: Option<String>,
    evidence: Option<ProbeEvidence>,
}

impl App {
    fn fail(&mut self, error: String) {
        self.fatal = Some(error);
        self.exit = true;
    }

    fn present(&mut self, qh: &QueueHandle<Self>, serial: u32, width: u32, height: u32) {
        if let Err(error) = self.try_present(qh, serial, width, height) {
            self.fail(error.to_string());
        }
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the one-shot protocol transaction is intentionally kept in wire order"
    )]
    fn try_present(
        &mut self,
        qh: &QueueHandle<Self>,
        serial: u32,
        width: u32,
        height: u32,
    ) -> Result<(), ProbeError> {
        if self.buffer.is_some() {
            return Ok(());
        }
        let feedback = self.feedback.as_ref().ok_or(ProbeError::DmabufV4Required)?;
        let fourcc = DrmFourcc::Xrgb8888 as u32;
        let modifier = u64::from(DrmModifier::Linear);
        let advertised = feedback.tranches().iter().any(|tranche| {
            tranche.formats.iter().any(|index| {
                feedback
                    .format_table()
                    .get(*index as usize)
                    .is_some_and(|entry| entry.format == fourcc && entry.modifier == modifier)
            })
        });
        if !advertised {
            return Err(ProbeError::MissingLinearXrgb);
        }

        let bo = self
            .gbm
            .create_buffer_object_with_modifiers::<()>(
                width,
                height,
                DrmFourcc::Xrgb8888,
                [Modifier::Linear].into_iter(),
            )
            .map_err(|error| ProbeError::Callback(format!("GBM allocation: {error}")))?;
        if bo.plane_count() != 1 {
            return Err(ProbeError::PlaneCount(bo.plane_count()));
        }
        let actual_modifier = u64::from(bo.modifier());
        if actual_modifier != modifier {
            return Err(ProbeError::Callback(format!(
                "GBM returned modifier {actual_modifier:#018x}, expected linear"
            )));
        }
        let dma_buf = bo
            .fd_for_plane(0)
            .map_err(|error| ProbeError::Callback(format!("DMA-BUF export: {error}")))?;
        let acquire_sync_file = self.egl.render(EglTarget {
            width,
            height,
            fourcc,
            modifier: actual_modifier,
            dma_buf: &dma_buf,
            offset: bo.offset(0),
            stride: bo.stride_for_plane(0),
        })?;

        let timeline_handle = self
            .timeline_handle
            .ok_or_else(|| ProbeError::Callback("timeline handle is absent".into()))?;
        let imported_acquire = self
            .drm
            .create_syncobj(false)
            .map_err(|error| ProbeError::Syncobj(format!("create acquire syncobj: {error}")))?;
        import_sync_file(&self.drm, imported_acquire, &acquire_sync_file)?;
        self.drm
            .syncobj_timeline_transfer(imported_acquire, timeline_handle, 0, ACQUIRE_POINT)
            .map_err(|error| {
                ProbeError::Syncobj(format!("transfer acquire point into timeline: {error}"))
            })?;
        self.drm
            .destroy_syncobj(imported_acquire)
            .map_err(|error| ProbeError::Syncobj(format!("destroy acquire syncobj: {error}")))?;
        let window = self.window.as_ref().ok_or_else(|| {
            ProbeError::Callback("window disappeared before first present".into())
        })?;
        let sync_manager = self
            .sync_surface
            .as_ref()
            .ok_or_else(|| ProbeError::Callback("sync surface is absent".into()))?;
        let timeline_proxy = self
            .timeline
            .as_ref()
            .ok_or_else(|| ProbeError::Callback("sync timeline proxy is absent".into()))?;

        let params = self
            .dmabuf_state
            .create_params(qh)
            .map_err(|error| ProbeError::Callback(format!("create DMA-BUF params: {error}")))?;
        params.add(
            dma_buf.as_fd(),
            0,
            bo.offset(0),
            bo.stride_for_plane(0),
            actual_modifier,
        );
        let width_i32 = i32::try_from(width).map_err(|_| ProbeError::Dimension)?;
        let height_i32 = i32::try_from(height).map_err(|_| ProbeError::Dimension)?;
        let (buffer, params_proxy) = params.create_immed(
            width_i32,
            height_i32,
            fourcc,
            zwp_linux_buffer_params_v1::Flags::empty(),
            qh,
        );
        params_proxy.destroy();

        self.transport.replace_feedback([FormatModifier {
            fourcc,
            modifier: actual_modifier,
        }]);
        self.transport.configure(Configure {
            serial,
            width,
            height,
            refresh_millihz: 0,
        });
        self.transport.acknowledge(serial)?;
        let metadata = BufferMetadata {
            id: BufferId(1),
            width,
            height,
            format: FormatModifier {
                fourcc,
                modifier: actual_modifier,
            },
            planes: vec![PlaneMetadata {
                index: 0,
                offset: bo.offset(0),
                stride: bo.stride_for_plane(0),
            }],
        };
        let accepted = self.transport.submit(
            metadata,
            vec![Damage {
                x: 0,
                y: 0,
                width,
                height,
            }],
            true,
        )?;

        let (acquire_hi, acquire_lo) = split_point(ACQUIRE_POINT);
        let (release_hi, release_lo) = split_point(RELEASE_POINT);
        sync_manager.set_acquire_point(timeline_proxy, acquire_hi, acquire_lo);
        sync_manager.set_release_point(timeline_proxy, release_hi, release_lo);
        window.wl_surface().attach(Some(&buffer), 0, 0);
        window
            .wl_surface()
            .damage_buffer(0, 0, width_i32, height_i32);
        window.wl_surface().frame(qh, window.wl_surface().clone());
        window.commit();

        self.evidence = Some(ProbeEvidence {
            schema_version: 1,
            render_node: self.render_node.clone(),
            gbm_backend: self.gbm.backend_name().to_owned(),
            gl_renderer: self.egl.renderer_name(),
            width,
            height,
            fourcc,
            modifier: actual_modifier,
            plane_count: bo.plane_count(),
            stride: bo.stride_for_plane(0),
            producer: "OpenGL ES framebuffer via EGL_EXT_image_dma_buf_import",
            acquire_fence: "EGL_ANDROID_native_fence_sync -> DRM syncobj timeline",
            compositor_sync: "wp_linux_drm_syncobj_v1",
            release_observed: false,
            cpu_readback: false,
            steady_state_cpu_copies: 0,
            drm_card_opened: false,
            frame_callbacks: 0,
        });
        self.submitted_frame = Some(accepted.frame_id);
        self.bo = Some(bo);
        self.buffer = Some(buffer);
        Ok(())
    }

    fn finish_release(&mut self) -> Result<(), ProbeError> {
        let handle = self
            .timeline_handle
            .ok_or_else(|| ProbeError::Callback("timeline handle is absent".into()))?;
        let drm = self.drm.try_clone()?;
        let (sender, receiver) = mpsc::sync_channel(1);
        std::thread::spawn(move || {
            let result =
                drm.syncobj_timeline_wait(&[handle], &[RELEASE_POINT], i64::MAX, true, true, false);
            let _ = sender.send(result);
        });
        let result = receiver
            .recv_timeout(Duration::from_secs(5))
            .map_err(|_| ProbeError::ReleaseTimeout)?;
        result.map_err(|error| ProbeError::Syncobj(error.to_string()))?;
        let frame = self
            .submitted_frame
            .take()
            .ok_or_else(|| ProbeError::Callback("submitted frame is absent".into()))?;
        self.transport.release(frame, true)?;
        self.drm
            .destroy_syncobj(handle)
            .map_err(|error| ProbeError::Syncobj(error.to_string()))?;
        self.timeline_handle = None;
        if let Some(evidence) = &mut self.evidence {
            evidence.release_observed = true;
            evidence.frame_callbacks = self.callbacks;
        }
        self.exit = true;
        Ok(())
    }
}

fn split_point(point: u64) -> (u32, u32) {
    let high = u32::try_from(point >> 32).unwrap_or_default();
    let low = u32::try_from(point & u64::from(u32::MAX)).unwrap_or_default();
    (high, low)
}

fn import_sync_file(
    drm: &DrmNode,
    handle: syncobj::Handle,
    sync_file: &OwnedFd,
) -> Result<(), ProbeError> {
    let mut error = [0_i8; 512];
    // SAFETY: both descriptors and the process-local syncobj handle are valid for
    // the ioctl; C only writes inside the provided bounded error array.
    let result = unsafe {
        droidloom_import_sync_file(
            drm.as_fd().as_raw_fd(),
            u32::from(handle),
            sync_file.as_raw_fd(),
            error.as_mut_ptr(),
            error.len(),
        )
    };
    if result == 0 {
        Ok(())
    } else {
        Err(ProbeError::Syncobj(c_error(&error)))
    }
}

impl CompositorHandler for App {
    fn scale_factor_changed(
        &mut self,
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
        _surface: &wl_surface::WlSurface,
        _new_factor: i32,
    ) {
    }

    fn transform_changed(
        &mut self,
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
        _surface: &wl_surface::WlSurface,
        _new_transform: wl_output::Transform,
    ) {
    }

    fn frame(
        &mut self,
        _conn: &Connection,
        qh: &QueueHandle<Self>,
        surface: &wl_surface::WlSurface,
        _time: u32,
    ) {
        self.callbacks = self.callbacks.saturating_add(1);
        if self.callbacks < self.target_callbacks {
            surface.frame(qh, surface.clone());
            surface.commit();
        } else if !self.detached {
            self.detached = true;
            surface.attach(None, 0, 0);
            surface.frame(qh, surface.clone());
            surface.commit();
        } else if let Err(error) = self.finish_release() {
            self.fail(error.to_string());
        }
    }

    fn surface_enter(
        &mut self,
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
        _surface: &wl_surface::WlSurface,
        _output: &wl_output::WlOutput,
    ) {
    }

    fn surface_leave(
        &mut self,
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
        _surface: &wl_surface::WlSurface,
        _output: &wl_output::WlOutput,
    ) {
    }
}

