fn main() {
    if let Err(error) = run() {
        eprintln!("droidloom-dmabuf-probe: {error}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), ProbeError> {
    let cli = Cli::parse();
    validate_render_node(&cli.render_node)?;
    let render_file = OpenOptions::new()
        .read(true)
        .write(true)
        .open(&cli.render_node)?;
    let gbm_file = render_file.try_clone()?;
    let drm = DrmNode(render_file);
    let gbm = GbmDevice::new(gbm_file)?;
    let gbm_pointer = gbm::AsRaw::<gbm_sys::gbm_device>::as_raw(&gbm)
        .cast_mut()
        .cast();
    let egl = EglRenderer::new(gbm_pointer)?;

    let conn = Connection::connect_to_env()?;
    let (globals, mut event_queue) = registry_queue_init(&conn)?;
    let qh = event_queue.handle();
    let compositor = CompositorState::bind(&globals, &qh)?;
    let xdg_shell = XdgShell::bind(&globals, &qh)?;
    let dmabuf_state = DmabufState::new(&globals, &qh);
    if !matches!(dmabuf_state.version(), Some(4..)) {
        return Err(ProbeError::DmabufV4Required);
    }
    let sync_manager: WpLinuxDrmSyncobjManagerV1 = globals.bind(&qh, 1..=1, ())?;

    let mut app = App {
        registry_state: RegistryState::new(&globals),
        output_state: OutputState::new(&globals, &qh),
        dmabuf_state,
        feedback: None,
        window: None,
        sync_surface: None,
        timeline: None,
        timeline_handle: None,
        drm,
        gbm,
        egl,
        bo: None,
        buffer: None,
        transport: PresentationState::default(),
        submitted_frame: None,
        render_node: cli.render_node,
        target_callbacks: cli.frame_callbacks.max(1),
        callbacks: 0,
        detached: false,
        exit: false,
        fatal: None,
        evidence: None,
    };

    app.dmabuf_state.get_default_feedback(&qh)?;
    while app.feedback.is_none() {
        event_queue.blocking_dispatch(&mut app)?;
    }

    let surface = compositor.create_surface(&qh);
    let window = xdg_shell.create_window(surface, WindowDecorations::None, &qh);
    window.set_title("Droidloom GLES DMA-BUF probe");
    window.set_app_id("org.droidloom.DmabufProbe");
    window.set_fullscreen(None);
    let sync_surface = sync_manager.get_surface(window.wl_surface(), &qh, ());
    let timeline_handle = app
        .drm
        .create_syncobj(false)
        .map_err(|error| ProbeError::Syncobj(error.to_string()))?;
    let timeline_fd = app
        .drm
        .syncobj_to_fd(timeline_handle, false)
        .map_err(|error| ProbeError::Syncobj(error.to_string()))?;
    let timeline = sync_manager.import_timeline(timeline_fd.as_fd(), &qh, ());
    window.commit();
    app.window = Some(window);
    app.sync_surface = Some(sync_surface);
    app.timeline = Some(timeline);
    app.timeline_handle = Some(timeline_handle);

    while !app.exit {
        event_queue.blocking_dispatch(&mut app)?;
    }
    if let Some(error) = app.fatal {
        return Err(ProbeError::Callback(error));
    }
    let evidence = app
        .evidence
        .ok_or_else(|| ProbeError::Callback("probe exited without evidence".into()))?;
    println!(
        "{}",
        serde_json::to_string_pretty(&evidence)
            .map_err(|error| ProbeError::Callback(error.to_string()))?
    );
    Ok(())
}

fn validate_render_node(path: &std::path::Path) -> Result<(), ProbeError> {
    let valid_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .and_then(|name| name.strip_prefix("renderD"))
        .is_some_and(|digits| {
            !digits.is_empty() && digits.bytes().all(|byte| byte.is_ascii_digit())
        });
    if path.parent() == Some(std::path::Path::new("/dev/dri")) && valid_name {
        Ok(())
    } else {
        Err(ProbeError::RenderNodePolicy(path.to_path_buf()))
    }
}

#include <EGL/egl.h>
#include <EGL/eglext.h>
#include <GLES2/gl2.h>
#include <GLES2/gl2ext.h>
#include <libdrm/drm.h>

#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>

struct droidloom_egl_renderer {
    EGLDisplay display;
    EGLContext context;
    EGLSurface surface;
    PFNEGLCREATEIMAGEKHRPROC create_image;
    PFNEGLDESTROYIMAGEKHRPROC destroy_image;
    PFNGLEGLIMAGETARGETTEXTURE2DOESPROC image_target_texture;
    PFNEGLCREATESYNCKHRPROC create_sync;
    PFNEGLDESTROYSYNCKHRPROC destroy_sync;
    PFNEGLDUPNATIVEFENCEFDANDROIDPROC duplicate_fence_fd;
    int has_modifier_import;
    char renderer[256];
};

static int fail(char *error, size_t error_size, const char *message) {
    if (error != NULL && error_size > 0) {
        (void)snprintf(error, error_size, "%s (egl=0x%04x gl=0x%04x)",
                       message, (unsigned int)eglGetError(), (unsigned int)glGetError());
    }
    return -1;
}

static int has_extension(const char *extensions, const char *needle) {
    if (extensions == NULL || needle == NULL || strchr(needle, ' ') != NULL) {
        return 0;
    }
    const size_t length = strlen(needle);
    const char *cursor = extensions;
    while ((cursor = strstr(cursor, needle)) != NULL) {
        const char before = cursor == extensions ? ' ' : cursor[-1];
        const char after = cursor[length];
        if ((before == ' ' || before == '\0') && (after == ' ' || after == '\0')) {
            return 1;
        }
        cursor += length;
    }
    return 0;
}

struct droidloom_egl_renderer *droidloom_egl_renderer_create(
    void *gbm_device, char *error, size_t error_size) {
    PFNEGLGETPLATFORMDISPLAYEXTPROC get_platform_display =
        (PFNEGLGETPLATFORMDISPLAYEXTPROC)eglGetProcAddress("eglGetPlatformDisplayEXT");
    if (get_platform_display == NULL) {
        fail(error, error_size, "EGL_EXT_platform_base is unavailable");
        return NULL;
    }

    struct droidloom_egl_renderer *renderer = calloc(1, sizeof(*renderer));
    if (renderer == NULL) {
        fail(error, error_size, "cannot allocate EGL renderer state");
        return NULL;
    }
    renderer->display = get_platform_display(EGL_PLATFORM_GBM_KHR, gbm_device, NULL);
    renderer->context = EGL_NO_CONTEXT;
    renderer->surface = EGL_NO_SURFACE;
    if (renderer->display == EGL_NO_DISPLAY || !eglInitialize(renderer->display, NULL, NULL)) {
        fail(error, error_size, "cannot initialize EGL on the render node");
        free(renderer);
        return NULL;
    }
    if (!eglBindAPI(EGL_OPENGL_ES_API)) {
        fail(error, error_size, "cannot bind the OpenGL ES API");
        eglTerminate(renderer->display);
        free(renderer);
        return NULL;
    }

    const EGLint config_attributes[] = {
        EGL_RENDERABLE_TYPE, EGL_OPENGL_ES2_BIT,
        EGL_RED_SIZE, 8,
        EGL_GREEN_SIZE, 8,
        EGL_BLUE_SIZE, 8,
        EGL_ALPHA_SIZE, 0,
        EGL_NONE,
    };
    EGLConfig config = NULL;
    EGLint config_count = 0;
    if (!eglChooseConfig(renderer->display, config_attributes, &config, 1, &config_count) ||
        config_count < 1) {
        fail(error, error_size, "cannot choose an EGL GBM config");
        eglTerminate(renderer->display);
        free(renderer);
        return NULL;
    }
    const EGLint context_attributes[] = {EGL_CONTEXT_CLIENT_VERSION, 2, EGL_NONE};
    renderer->context = eglCreateContext(renderer->display, config, EGL_NO_CONTEXT,
                                         context_attributes);
    if (renderer->context == EGL_NO_CONTEXT ||
        !eglMakeCurrent(renderer->display, EGL_NO_SURFACE, EGL_NO_SURFACE,
                        renderer->context)) {
        fail(error, error_size, "cannot create the GLES context");
        if (renderer->context != EGL_NO_CONTEXT) {
            eglDestroyContext(renderer->display, renderer->context);
        }
        eglTerminate(renderer->display);
        free(renderer);
        return NULL;
    }

    renderer->create_image =
        (PFNEGLCREATEIMAGEKHRPROC)eglGetProcAddress("eglCreateImageKHR");
    renderer->destroy_image =
        (PFNEGLDESTROYIMAGEKHRPROC)eglGetProcAddress("eglDestroyImageKHR");
    renderer->image_target_texture =
        (PFNGLEGLIMAGETARGETTEXTURE2DOESPROC)eglGetProcAddress(
            "glEGLImageTargetTexture2DOES");
    renderer->create_sync =
        (PFNEGLCREATESYNCKHRPROC)eglGetProcAddress("eglCreateSyncKHR");
    renderer->destroy_sync =
        (PFNEGLDESTROYSYNCKHRPROC)eglGetProcAddress("eglDestroySyncKHR");
    renderer->duplicate_fence_fd =
        (PFNEGLDUPNATIVEFENCEFDANDROIDPROC)eglGetProcAddress(
            "eglDupNativeFenceFDANDROID");
    const char *extensions = eglQueryString(renderer->display, EGL_EXTENSIONS);
    renderer->has_modifier_import =
        has_extension(extensions, "EGL_EXT_image_dma_buf_import_modifiers");
    if (renderer->create_image == NULL || renderer->destroy_image == NULL ||
        renderer->image_target_texture == NULL || renderer->create_sync == NULL ||
        renderer->destroy_sync == NULL || renderer->duplicate_fence_fd == NULL ||
        !has_extension(extensions, "EGL_EXT_image_dma_buf_import") ||
        !has_extension(extensions, "EGL_ANDROID_native_fence_sync")) {
        fail(error, error_size, "required DMA-BUF/native-fence EGL extensions are unavailable");
        eglMakeCurrent(renderer->display, EGL_NO_SURFACE, EGL_NO_SURFACE, EGL_NO_CONTEXT);
        eglDestroyContext(renderer->display, renderer->context);
        eglTerminate(renderer->display);
        free(renderer);
        return NULL;
    }

    const GLubyte *name = glGetString(GL_RENDERER);
    (void)snprintf(renderer->renderer, sizeof(renderer->renderer), "%s",
                   name == NULL ? "unknown" : (const char *)name);
    return renderer;
}

const char *droidloom_egl_renderer_name(const struct droidloom_egl_renderer *renderer) {
    return renderer == NULL ? "unknown" : renderer->renderer;
}

int droidloom_egl_render_dmabuf(struct droidloom_egl_renderer *renderer,
                                int width, int height, uint32_t fourcc,
                                uint64_t modifier, int dma_buf_fd,
                                uint32_t offset, uint32_t stride,
                                int *fence_fd, char *error, size_t error_size) {
    if (renderer == NULL || width <= 0 || height <= 0 || dma_buf_fd < 0 ||
        stride == 0 || fence_fd == NULL) {
        return fail(error, error_size, "invalid GLES DMA-BUF render arguments");
    }
    if (!eglMakeCurrent(renderer->display, EGL_NO_SURFACE, EGL_NO_SURFACE,
                        renderer->context)) {
        return fail(error, error_size, "cannot make the GLES context current");
    }

    EGLint attributes[32];
    size_t index = 0;
#define ADD_ATTRIBUTE(name, value) \
    do {                             \
        attributes[index++] = name;  \
        attributes[index++] = value; \
    } while (0)
    ADD_ATTRIBUTE(EGL_WIDTH, width);
    ADD_ATTRIBUTE(EGL_HEIGHT, height);
    ADD_ATTRIBUTE(EGL_LINUX_DRM_FOURCC_EXT, (EGLint)fourcc);
    ADD_ATTRIBUTE(EGL_DMA_BUF_PLANE0_FD_EXT, dma_buf_fd);
    ADD_ATTRIBUTE(EGL_DMA_BUF_PLANE0_OFFSET_EXT, (EGLint)offset);
    ADD_ATTRIBUTE(EGL_DMA_BUF_PLANE0_PITCH_EXT, (EGLint)stride);
    if (renderer->has_modifier_import) {
        ADD_ATTRIBUTE(EGL_DMA_BUF_PLANE0_MODIFIER_LO_EXT, (EGLint)(modifier & 0xffffffffu));
        ADD_ATTRIBUTE(EGL_DMA_BUF_PLANE0_MODIFIER_HI_EXT, (EGLint)(modifier >> 32));
    } else if (modifier != 0) {
        return fail(error, error_size, "EGL modifier import is unavailable for a non-linear BO");
    }
    attributes[index++] = EGL_NONE;
#undef ADD_ATTRIBUTE

    EGLImageKHR image = renderer->create_image(
        renderer->display, EGL_NO_CONTEXT, EGL_LINUX_DMA_BUF_EXT, NULL, attributes);
    if (image == EGL_NO_IMAGE_KHR) {
        return fail(error, error_size, "cannot import GBM DMA-BUF into EGL");
    }

    GLuint texture = 0;
    GLuint framebuffer = 0;
    glGenTextures(1, &texture);
    glBindTexture(GL_TEXTURE_2D, texture);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    renderer->image_target_texture(GL_TEXTURE_2D, image);
    glGenFramebuffers(1, &framebuffer);
    glBindFramebuffer(GL_FRAMEBUFFER, framebuffer);
    glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, texture, 0);
    if (glCheckFramebufferStatus(GL_FRAMEBUFFER) != GL_FRAMEBUFFER_COMPLETE) {
        glDeleteFramebuffers(1, &framebuffer);
        glDeleteTextures(1, &texture);
        renderer->destroy_image(renderer->display, image);
        return fail(error, error_size, "DMA-BUF GLES framebuffer is incomplete");
    }

    glViewport(0, 0, width, height);
    glDisable(GL_SCISSOR_TEST);
    glClearColor(0.02f, 0.35f, 0.48f, 1.0f);
    glClear(GL_COLOR_BUFFER_BIT);

    EGLSyncKHR sync = renderer->create_sync(renderer->display,
                                            EGL_SYNC_NATIVE_FENCE_ANDROID, NULL);
    if (sync == EGL_NO_SYNC_KHR) {
        glDeleteFramebuffers(1, &framebuffer);
        glDeleteTextures(1, &texture);
        renderer->destroy_image(renderer->display, image);
        return fail(error, error_size, "cannot create the GLES native fence");
    }
    glFlush();
    *fence_fd = renderer->duplicate_fence_fd(renderer->display, sync);
    renderer->destroy_sync(renderer->display, sync);
    glDeleteFramebuffers(1, &framebuffer);
    glDeleteTextures(1, &texture);
    renderer->destroy_image(renderer->display, image);
    if (*fence_fd < 0) {
        return fail(error, error_size, "cannot export the GLES native fence");
    }
    return 0;
}

void droidloom_egl_renderer_destroy(struct droidloom_egl_renderer *renderer) {
    if (renderer == NULL) {
        return;
    }
    eglMakeCurrent(renderer->display, EGL_NO_SURFACE, EGL_NO_SURFACE, EGL_NO_CONTEXT);
    if (renderer->surface != EGL_NO_SURFACE) {
        eglDestroySurface(renderer->display, renderer->surface);
    }
    eglDestroyContext(renderer->display, renderer->context);
    eglTerminate(renderer->display);
    free(renderer);
}

int droidloom_import_sync_file(int drm_fd, uint32_t syncobj_handle,
                               int sync_file_fd, char *error, size_t error_size) {
    struct drm_syncobj_handle arguments = {
        .handle = syncobj_handle,
        .flags = DRM_SYNCOBJ_FD_TO_HANDLE_FLAGS_IMPORT_SYNC_FILE,
        .fd = sync_file_fd,
    };
    if (ioctl(drm_fd, DRM_IOCTL_SYNCOBJ_FD_TO_HANDLE, &arguments) == 0) {
        return 0;
    }
    if (error != NULL && error_size > 0) {
        (void)snprintf(error, error_size, "DRM sync-file import: %s", strerror(errno));
    }
    return -1;
}

//! Android notifications on the desktop session bus. No work runs on the render loop.
use async_io::Async;
use futures_lite::{
    StreamExt, future,
    io::{AsyncReadExt, AsyncWriteExt},
};
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, HashMap},
    fs, io,
    os::{
        fd::AsRawFd,
        unix::{
            fs::{FileTypeExt, PermissionsExt},
            net::{UnixListener, UnixStream},
        },
    },
    path::PathBuf,
    time::Duration,
};
use zbus::{Connection, MatchRule, Message, MessageStream, Proxy, message::Type, zvariant::Value};
const NAME: &str = "org.freedesktop.Notifications";
const PATH: &str = "/org/freedesktop/Notifications";
const MAX_FRAME: usize = 131072;
const MAX_ACTIVE: usize = 256;
type Result<T> = std::result::Result<T, Box<dyn std::error::Error + Send + Sync>>;

pub struct Bridge {
    stop: UnixStream,
    path: PathBuf,
}
impl Bridge {
    pub fn start(path: PathBuf) -> io::Result<Self> {
        match fs::symlink_metadata(&path) {
            Ok(m) if m.file_type().is_socket() => fs::remove_file(&path)?,
            Ok(_) => return Err(io::Error::other("notification endpoint is not a socket")),
            Err(e) if e.kind() == io::ErrorKind::NotFound => (),
            Err(e) => return Err(e),
        }
        let listener = Async::new(UnixListener::bind(&path)?)?;
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600))?;
        let (stop, stopped) = UnixStream::pair()?;
        let stopped = Async::new(stopped)?;
        let state_path = path.with_extension("state");
        std::thread::Builder::new()
            .name("droidloom-notifications".into())
            .spawn(move || {
                droidloom_cpu_placement::current(droidloom_cpu_placement::Role::Background);
                future::block_on(async move {
                    loop {
                        let result = future::race(run(&listener, &state_path), async {
                            let mut b = [0];
                            let _ = (&stopped).read(&mut b).await;
                            Ok(())
                        })
                        .await;
                        match result {
                            Ok(()) => break,
                            Err(_) => eprintln!(
                                "Droidloom notifications: session bus disconnected; retrying"
                            ),
                        }
                        let stop = future::race(
                            async {
                                async_io::Timer::after(Duration::from_secs(2)).await;
                                false
                            },
                            async {
                                let mut b = [0];
                                let _ = (&stopped).read(&mut b).await;
                                true
                            },
                        )
                        .await;
                        if stop {
                            break;
                        }
                    }
                });
            })?;
        eprintln!("DROIDLOOM_NOTIFICATIONS_ABI=1;");
        Ok(Self { stop, path })
    }
}
impl Drop for Bridge {
    fn drop(&mut self) {
        let _ = self.stop.shutdown(std::net::Shutdown::Both);
        let _ = fs::remove_file(&self.path);
    }
}
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct Action {
    key: String,
    label: String,
}
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct Note {
    key: String,
    version: String,
    package: String,
    app: String,
    title: String,
    body: String,
    actions: Vec<Action>,
    urgency: u8,
    ongoing: bool,
    clearable: bool,
    icon: Vec<u8>,
}
impl Note {
    fn valid(&self) -> bool {
        !self.key.is_empty()
            && self.key.len() <= 2048
            && !self.version.is_empty()
            && self.version.len() <= 96
            && self.package.len() <= 256
            && self
                .package
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'_')
            && self.app.len() <= 1024
            && self.title.len() <= 8192
            && self.body.len() <= 32768
            && [&self.key, &self.version, &self.app, &self.title, &self.body]
                .iter()
                .all(|s| !s.contains('\0'))
            && self.urgency <= 2
            && (self.icon.is_empty() || self.icon.len() == 48 * 48 * 4)
            && self.actions.len() <= 17
            && self.actions.iter().all(|a| {
                (a.key == "default"
                    || a.key
                        .strip_prefix("action-")
                        .is_some_and(|n| n.parse::<u8>().is_ok_and(|i| i < 16)))
                    && a.label.len() <= 1024
                    && !a.label.contains('\0')
            })
    }
}
#[derive(Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
enum Frame {
    Hello { abi: u32 },
    Begin,
    Post { notification: Note },
    End,
}
struct Peer {
    socket: Async<UnixStream>,
    buffer: Vec<u8>,
    hello: bool,
    snapshot: Option<BTreeMap<String, Note>>,
}
impl Peer {
    fn ingest(&mut self, bytes: &[u8]) -> Result<Vec<BTreeMap<String, Note>>> {
        self.buffer.extend_from_slice(bytes);
        let mut complete = vec![];
        loop {
            if self.buffer.len() < 4 {
                break;
            }
            let length = u32::from_be_bytes(self.buffer[..4].try_into()?) as usize;
            if length == 0 || length > MAX_FRAME {
                return Err("invalid notification frame".into());
            }
            if self.buffer.len() < length + 4 {
                break;
            }
            let frame: Frame = serde_json::from_slice(&self.buffer[4..length + 4])?;
            self.buffer.drain(..length + 4);
            match frame {
                Frame::Hello { abi: 1 } if !self.hello => self.hello = true,
                Frame::Begin if self.hello && self.snapshot.is_none() => {
                    self.snapshot = Some(BTreeMap::new())
                }
                Frame::Post { notification: n } if self.hello && n.valid() => {
                    let snapshot = self.snapshot.as_mut().ok_or("post outside snapshot")?;
                    if snapshot.len() >= MAX_ACTIVE || snapshot.insert(n.key.clone(), n).is_some() {
                        return Err("invalid notification snapshot".into());
                    }
                }
                Frame::End if self.hello => {
                    complete.push(self.snapshot.take().ok_or("end outside snapshot")?)
                }
                _ => return Err("invalid notification sequence".into()),
            }
        }
        Ok(complete)
    }
    async fn command(&self, note: &Note, action: Option<&str>) -> Result<()> {
        let mut command = serde_json::json!({"type":if action.is_some(){"action"}else{"dismiss"},"key":note.key,"version":note.version});
        if let Some(a) = action {
            command["action"] = a.into();
        }
        self.send(command).await
    }
    async fn send(&self, command: serde_json::Value) -> Result<()> {
        let body = serde_json::to_vec(&command)?;
        let mut data = (body.len() as u32).to_be_bytes().to_vec();
        data.extend(body);
        future::race(
            async { (&self.socket).write_all(&data).await.map_err(Into::into) },
            async {
                async_io::Timer::after(Duration::from_secs(3)).await;
                Err("notification command timeout".into())
            },
        )
        .await
    }
}
#[derive(Default, Serialize, Deserialize)]
struct Record {
    id: Option<u32>,
    version: String,
    hidden: bool,
    #[serde(skip)]
    note: Option<Note>,
}
#[derive(Default, Serialize, Deserialize)]
struct State {
    #[serde(default)]
    bus_id: String,
    owner: String,
    records: BTreeMap<String, Record>,
}
impl State {
    fn save(&self, path: &PathBuf) -> io::Result<()> {
        let tmp = path.with_extension("new");
        use std::io::Write;
        use std::os::unix::fs::OpenOptionsExt;
        let mut file = fs::OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .mode(0o600)
            .open(&tmp)?;
        file.write_all(&serde_json::to_vec(self)?)?;
        fs::rename(tmp, path)
    }
    fn owner(&mut self, owner: String) {
        if self.owner != owner {
            self.owner = owner;
            for record in self.records.values_mut() {
                record.id = None;
                record.hidden = false;
            }
        }
    }
}
struct Desktop<'a> {
    proxy: Proxy<'a>,
    capabilities: Vec<String>,
}
impl Desktop<'_> {
    async fn notify(&self, n: &Note, replaces: u32) -> zbus::Result<u32> {
        let actions: Vec<&str> = if self.capabilities.iter().any(|c| c == "actions") {
            n.actions
                .iter()
                .flat_map(|a| [a.key.as_str(), a.label.as_str()])
                .collect()
        } else {
            vec![]
        };
        let mut hints: HashMap<&str, Value<'_>> = HashMap::new();
        hints.insert("urgency", Value::from(n.urgency));
        hints.insert("resident", Value::from(n.ongoing));
        // Android retains sound policy, including channel preferences and DND.
        hints.insert("suppress-sound", Value::from(true));
        if !n.icon.is_empty() {
            hints.insert(
                "image-data",
                Value::from((48i32, 48i32, 192i32, true, 8i32, 4i32, n.icon.clone())),
            );
        }
        let body = if self.capabilities.iter().any(|c| c == "body-markup") {
            escape_markup(&n.body)
        } else {
            n.body.clone()
        };
        self.proxy
            .call(
                "Notify",
                &(
                    &n.app,
                    replaces,
                    "application-x-executable",
                    if n.title.is_empty() { &n.app } else { &n.title },
                    &body,
                    actions,
                    hints,
                    // Android's ongoing flag governs cancellation, not popup lifetime.
                    // Let the desktop choose its normal timeout; expiry leaves Android active.
                    -1i32,
                ),
            )
            .await
    }
    async fn close(&self, id: u32) {
        let _: zbus::Result<()> = self.proxy.call("CloseNotification", &(id,)).await;
    }
}
fn escape_markup(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}
async fn reconcile(
    state: &mut State,
    snapshot: BTreeMap<String, Note>,
    desktop: &Desktop<'_>,
) -> Result<()> {
    let removed: Vec<_> = state
        .records
        .keys()
        .filter(|k| !snapshot.contains_key(*k))
        .cloned()
        .collect();
    for key in removed {
        if let Some(record) = state.records.remove(&key) {
            if let Some(id) = record.id {
                desktop.close(id).await;
            }
        }
    }
    for (key, note) in snapshot {
        let record = state.records.entry(key).or_default();
        if record.version != note.version {
            record.hidden = false;
        }
        let changed = record.version != note.version;
        record.version = note.version.clone();
        record.note = Some(note.clone());
        if !state.owner.is_empty() && !record.hidden && (changed || record.id.is_none()) {
            record.id = Some(desktop.notify(&note, record.id.unwrap_or(0)).await?);
        }
    }
    Ok(())
}
enum Event {
    Accept(io::Result<(Async<UnixStream>, std::os::unix::net::SocketAddr)>),
    Data(io::Result<Vec<u8>>),
    Signal(Option<zbus::Result<Message>>),
    Owner(Option<zbus::Result<Message>>),
}
async fn read_peer(peer: Option<&Peer>) -> Event {
    let Some(peer) = peer else {
        return future::pending().await;
    };
    let mut bytes = vec![0; 8192];
    Event::Data(match (&peer.socket).read(&mut bytes).await {
        Ok(n) => {
            bytes.truncate(n);
            Ok(bytes)
        }
        Err(e) => Err(e),
    })
}
async fn run(listener: &Async<UnixListener>, state_path: &PathBuf) -> Result<()> {
    let conn = zbus::connection::Builder::session()?
        .method_timeout(Duration::from_secs(3))
        .build()
        .await?;
    serve(listener, state_path, conn, 0).await
}
async fn serve(
    listener: &Async<UnixListener>,
    state_path: &PathBuf,
    conn: Connection,
    peer_uid: u32,
) -> Result<()> {
    let rule = MatchRule::builder()
        .msg_type(Type::Signal)
        .interface(NAME)?
        .path(PATH)?
        .build();
    let mut signals = MessageStream::for_match_rule(rule, &conn, Some(128)).await?;
    let rule = MatchRule::builder()
        .msg_type(Type::Signal)
        .sender("org.freedesktop.DBus")?
        .interface("org.freedesktop.DBus")?
        .member("NameOwnerChanged")?
        .add_arg(NAME)?
        .build();
    let mut owners = MessageStream::for_match_rule(rule, &conn, Some(16)).await?;
    let bus = zbus::fdo::DBusProxy::new(&conn).await?;
    let proxy = Proxy::new(&conn, NAME, PATH, NAME).await?;
    let capabilities = proxy.call("GetCapabilities", &()).await.unwrap_or_default();
    let owner = bus
        .get_name_owner(NAME.try_into()?)
        .await
        .map(|s| s.to_string())
        .unwrap_or_default();
    let mut desktop = Desktop {
        proxy,
        capabilities,
    };
    let mut state: State = fs::read(state_path)
        .ok()
        .filter(|b| b.len() < 1024 * 1024)
        .and_then(|b| serde_json::from_slice(&b).ok())
        .unwrap_or_default();
    if state.records.len() > MAX_ACTIVE {
        state = State::default();
    }
    let bus_id = bus.get_id().await?.to_string();
    if state.bus_id != bus_id {
        state.owner(String::new());
        state.bus_id = bus_id;
    }
    state.owner(owner);
    let mut peer: Option<Peer> = None;
    loop {
        let event = future::race(
            future::race(
                async { Event::Accept(listener.accept().await) },
                read_peer(peer.as_ref()),
            ),
            future::race(async { Event::Signal(signals.next().await) }, async {
                Event::Owner(owners.next().await)
            }),
        )
        .await;
        match event {
            Event::Accept(Ok((socket, _))) => {
                if !root_peer(socket.get_ref(), peer_uid)? {
                    continue;
                }
                peer = Some(Peer {
                    socket,
                    buffer: vec![],
                    hello: false,
                    snapshot: None,
                });
                eprintln!("Droidloom notifications: Android connected");
            }
            Event::Accept(Err(e)) => return Err(e.into()),
            Event::Data(Ok(bytes)) if !bytes.is_empty() => {
                let had_hello = peer.as_ref().unwrap().hello;
                match peer.as_mut().unwrap().ingest(&bytes) {
                    Ok(snapshots) => {
                        if !had_hello && peer.as_ref().unwrap().hello {
                            if peer
                                .as_ref()
                                .unwrap()
                                .send(serde_json::json!({"type":"hello","abi":1}))
                                .await
                                .is_err()
                            {
                                peer = None;
                                continue;
                            }
                        }
                        for snapshot in snapshots {
                            reconcile(&mut state, snapshot, &desktop).await?;
                            state.save(state_path)?;
                        }
                    }
                    Err(_) => {
                        eprintln!("Droidloom notifications: invalid Android frame; disconnected");
                        peer = None;
                    }
                }
            }
            Event::Data(_) => peer = None,
            Event::Owner(Some(Ok(message))) => {
                let (_, _, owner): (String, String, String) = message.body().deserialize()?;
                if owner == state.owner {
                    continue;
                }
                state.owner(owner);
                desktop.capabilities = if state.owner.is_empty() {
                    vec![]
                } else {
                    desktop
                        .proxy
                        .call("GetCapabilities", &())
                        .await
                        .unwrap_or_default()
                };
                let snapshot = state
                    .records
                    .iter()
                    .filter_map(|(k, r)| r.note.clone().map(|n| (k.clone(), n)))
                    .collect();
                reconcile(&mut state, snapshot, &desktop).await?;
                state.save(state_path)?;
            }
            Event::Signal(Some(Ok(message))) => {
                if message.header().sender().map(|s| s.as_str()) != Some(state.owner.as_str()) {
                    continue;
                }
                match message.header().member().map(|s| s.as_str()) {
                    Some("ActionInvoked") => {
                        let (id, action): (u32, String) = message.body().deserialize()?;
                        if let Some(note) = state
                            .records
                            .values()
                            .find(|r| r.id == Some(id))
                            .and_then(|r| r.note.as_ref())
                        {
                            if note.actions.iter().any(|a| a.key == action) {
                                if let Some(p) = peer.as_ref() {
                                    if p.command(note, Some(&action)).await.is_err() {
                                        peer = None;
                                    }
                                }
                            }
                        }
                    }
                    Some("NotificationClosed") => {
                        let (id, reason): (u32, u32) = message.body().deserialize()?;
                        if let Some(record) = state.records.values_mut().find(|r| r.id == Some(id))
                        {
                            record.id = None;
                            record.hidden = true;
                            if reason == 2 {
                                if let (Some(note), Some(p)) = (&record.note, &peer) {
                                    if note.clearable && p.command(note, None).await.is_err() {
                                        peer = None;
                                    }
                                }
                            }
                        }
                        state.save(state_path)?;
                    }
                    _ => (),
                }
            }
            Event::Owner(_) | Event::Signal(_) => return Err("session bus closed".into()),
        }
    }
}
fn root_peer(s: &UnixStream, expected_uid: u32) -> io::Result<bool> {
    let mut cred = libc::ucred {
        pid: 0,
        uid: !0,
        gid: !0,
    };
    let mut length = std::mem::size_of_val(&cred) as libc::socklen_t;
    // SAFETY: live socket and writable ucred buffer of the supplied size.
    if unsafe {
        libc::getsockopt(
            s.as_raw_fd(),
            libc::SOL_SOCKET,
            libc::SO_PEERCRED,
            (&raw mut cred).cast(),
            &raw mut length,
        )
    } != 0
    {
        return Err(io::Error::last_os_error());
    }
    Ok(cred.uid == expected_uid)
}

#[cfg(test)]
mod tests;
